	@Test
	void buffersInterleavedExistingAnchorsUntilFlush() throws Exception {
		seed(2, tuple(1, 10), tuple(1, 20));
		seed(2, tuple(1, 100), tuple(1, 110));
		var before = readTuples(4, 2);
		try (MemoryStack stack = MemoryStack.stackPush()) {
			MDBVal key = MDBVal.malloc(stack);
			MDBVal data = MDBVal.malloc(stack);
			assertEquals(MDB_SUCCESS, updater.add(cursor, key, data, tuple(1, 15)));
			assertEquals(MDB_SUCCESS, updater.add(cursor, key, data, tuple(1, 105)));
			assertEquals(MDB_SUCCESS, updater.add(cursor, key, data, tuple(1, 17)));
			assertEquals(before, readTuples(4, 2), "changing anchors must not flush pending updates");
			assertEquals(MDB_KEYEXIST, updater.add(cursor, key, data, tuple(1, 15)));
			assertEquals(MDB_KEYEXIST, updater.add(cursor, key, data, tuple(1, 110)));
			assertEquals(MDB_KEYEXIST, updater.add(cursor, key, data, tuple(1, 100)));
			updater.flush(cursor, key, data);
		}
		assertTuples(4, 2, tuple(1, 10), tuple(1, 15), tuple(1, 17), tuple(1, 20),
				tuple(1, 100), tuple(1, 105), tuple(1, 110));
	}

