		seed(2, tuple(2, 10), tuple(2, 20));
		try (MemoryStack stack = MemoryStack.stackPush()) {
			MDBVal key = MDBVal.malloc(stack);
			MDBVal data = MDBVal.malloc(stack);
			assertEquals(MDB_SUCCESS, updater.add(cursor, key, data, tuple(1, 15)));
			assertEquals(MDB_SUCCESS, updater.add(cursor, key, data, tuple(2, 15)));
			var other = stack.mallocInt(1);
			E(mdb_dbi_open(transaction, "other", MDB_CREATE, other));
			ByteBuffer keyBuffer = stack.malloc(8);
			ByteBuffer dataBuffer = stack.calloc(4000);
			for (int i = 0; i < 200; i++) {
				keyBuffer.clear().putLong(i).flip();
				E(mdb_put(transaction, other.get(0), key.mv_data(keyBuffer), data.mv_data(dataBuffer), 0));
			}
			assertEquals(MDB_KEYEXIST, updater.add(cursor, key, data, tuple(1, 20)));
			updater.flush(cursor, key, data);
		}
		assertTuples(4, 2, tuple(1, 10), tuple(1, 15), tuple(1, 20),
				tuple(2, 10), tuple(2, 15), tuple(2, 20));
