	@Test
	void fullAlignedBatchesReportOnlyUniqueInsertionsAndPromotions() throws Exception {
		long[] subjects = new long[64];
		long[] predicates = new long[64];
		long[] objects = new long[64];
		long[] contexts = new long[64];
		for (int i = 0; i < 64; i++) {
			subjects[i] = 100 + i % 32;
			predicates[i] = 10;
			objects[i] = 200 + i % 32;
			contexts[i] = 1;
		}
		Path storeDirectory = Files.createDirectory(directory.resolve("triples"));
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,ospc,psoc")
				.setTripleDBSize(16L * 1024 * 1024);
		try (TripleStore store = new TripleStore(storeDirectory.toFile(), config, null)) {
			List<Integer> callbacks = new ArrayList<>();
			store.startTransaction();
			store.storeTriplesAligned(subjects, predicates, objects, contexts, 64, false, callbacks::add);
			store.commit();
			assertEquals(32, callbacks.size(), "pending duplicates must not increment batch counts");
			callbacks.clear();
			store.startTransaction();
			store.storeTriplesAligned(subjects, predicates, objects, contexts, 64, true, callbacks::add);
			store.commit();
			assertEquals(32, callbacks.size(), "promotion must report each unique tuple once");
			callbacks.clear();
			store.startTransaction();
			store.storeTriplesAligned(subjects, predicates, objects, contexts, 64, true, callbacks::add);
			store.commit();
			assertEquals(List.of(), callbacks, "existing duplicates must not increment batch counts");
			try (var txn = store.getTxnManager().createReadTxn();
					var rows = store.getTriples(txn, -1, -1, -1, -1, true);
					var inferred = store.getTriples(txn, -1, -1, -1, -1, false)) {
				int count = 0;
				while (rows.next() != null) {
					count++;
				}
				assertEquals(32, count);
				assertEquals(null, inferred.next());
			}
		}
	}

	@ParameterizedTest
	@ValueSource(ints = { 0, 1, 2, 3, 4 })
	void randomizedBatchesMatchOrderedSet(int splitPoint) throws Exception {
		updater.reset(4, splitPoint);
		var expected = new TreeSet<long[]>(Arrays::compare);
		Random random = new Random(7981);
		try (MemoryStack stack = MemoryStack.stackPush()) {
			MDBVal key = MDBVal.malloc(stack);
			MDBVal data = MDBVal.malloc(stack);
			for (int round = 0; round < 3; round++) {
				for (int i = 0; i < 2000; i++) {
					long[] tuple = { random.nextInt(4), random.nextInt(4),
							random.nextInt(4), random.nextInt(64) };
					int status = expected.add(tuple) ? MDB_SUCCESS : MDB_KEYEXIST;
					assertEquals(status, updater.add(cursor, key, data, tuple), Arrays.toString(tuple));
				}
				updater.flush(cursor, key, data);
				assertTuples(4, splitPoint, expected.toArray(long[][]::new));
			}
		}
	}

	private static long[] tuple(long prefix, long value) {
		return new long[] { prefix, 1, 0, value };
	}

	private void seed(int splitPoint, long[]... tuples) throws IOException {
		try (MemoryStack stack = MemoryStack.stackPush()) {
			ChunkOutput output = new ChunkOutput(Chunks.MAX_CHUNK_SIZE, tuples[0].length, splitPoint);
			for (long[] tuple : tuples) {
				assertTrue(output.addTuple(tuple));
			}
			ByteBuffer key = stack.malloc(TripleIndex.MAX_KEY_LENGTH);
			ByteBuffer data = stack.malloc(4096);
			output.write(key, data);
			E(mdb_cursor_put(cursor, MDBVal.malloc(stack).mv_data(key.flip()),
					MDBVal.malloc(stack).mv_data(data.flip()), 0));
		}
	}

	private List<List<Long>> readTuples(int tupleLength, int splitPoint) throws IOException {
		List<List<Long>> result = new ArrayList<>();
		try (MemoryStack stack = MemoryStack.stackPush()) {
			MDBVal key = MDBVal.malloc(stack);
			MDBVal data = MDBVal.malloc(stack);
			int rc = E(mdb_cursor_get(cursor, key, data, MDB_FIRST));
			while (rc == MDB_SUCCESS) {
				ChunkInput input = new ChunkInput(key.mv_data(), data.mv_data(), tupleLength, splitPoint);
				long[] tuple;
				int size = 0;
				while ((tuple = input.next()) != null) {
					result.add(Arrays.stream(tuple, 0, tupleLength).boxed().toList());
					size++;
				}
				assertTrue(size <= Chunks.MAX_CHUNK_SIZE);
				rc = E(mdb_cursor_get(cursor, key, data, MDB_NEXT));
			}
		}
		return result;
	}

	private void assertTuples(int tupleLength, int splitPoint, long[]... tuples) throws IOException {
		Arrays.sort(tuples, Arrays::compare);
		List<List<Long>> expected = Arrays.stream(tuples)
				.map(tuple -> Arrays.stream(tuple).boxed().toList())
				.toList();
		assertEquals(expected, readTuples(tupleLength, splitPoint));
	}
